            reader.readAsDataURL(imgData);
            return new Promise((resolve) => {
              reader.onloadend = function () {
                const base64data = reader.result;
                doc.addImage(base64data, 'PNG', 0, 0, 89, 58);
                resolve(true);
              };
            });
